/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Medical Profile" (boardui.com/templates/medical-profile).
 * No BoardUI source was used.
 */
"use client";

import { useMemo, useState, type MouseEvent } from "react";
import type { CalendarDate } from "@internationalized/date";
import { parseDate } from "@internationalized/date";
import {
  RiAsterisk,
  RiCalendarCheckLine,
  RiFileList3Line,
  RiHeartPulseLine,
  RiMedicineBottleLine,
  RiTestTubeLine,
} from "@remixicon/react";

import { DASHBOARD_NAV, DashboardSidebar } from "@/components/motion/dashboard-sidebar";
import { DashboardPageHeader } from "@/components/motion/dashboard-page-header";
import { NotificationBellBadge, type BellNotification } from "@/components/motion/notification-bell-badge";
import { StepsCard } from "@/components/motion/steps-card";
import { SleepScoreCard } from "@/components/motion/sleep-score-card";
import { MostActiveDaysCard, formatLongDate, sampleDayActivity } from "@/components/motion/most-active-days-card";
import { ActivityRingsCard } from "@/components/motion/activity-rings-card";
import { ImportantAlertsCard } from "@/components/motion/important-alerts-card";
import { PatientsTable, type Patient, type PatientAction } from "@/components/motion/patients-table";
import { Toaster, toast } from "@/components/motion/toast";
import { cx } from "@/lib/cx";
import {
  FileReportDialog,
  PatientProfileCard,
  REPORT_KINDS,
  SectionFilter,
  WorkspacePlaceholder,
  type DashboardSection,
  type FiledReport,
} from "@/components/motion/medical-profile-parts";

/* -------------------------------------------------------------------- data */

export const MEDICAL_PATIENTS: Patient[] = [
  { id: "p1", name: "John Clarkson", avatarColor: "blue", admission: "outpatient", status: "recovering", conditions: ["Pregnancy", "Post-op"], nextAppointment: "2026-05-14" },
  { id: "p2", name: "Aspen Lubin", avatarColor: "lime", admission: "inpatient", status: "treatment", conditions: ["Hypertension"], nextAppointment: "2026-10-15" },
  { id: "p3", name: "Michael Ekstrom", avatarColor: "pink", admission: "inpatient", status: "observation", conditions: ["Asthma", "Migraine"], nextAppointment: "2026-03-25" },
  { id: "p4", name: "Kianna Vaccaro", avatarColor: "neutral", admission: "inpatient", status: "stable", conditions: ["Post-op"], nextAppointment: "2026-10-03" },
  { id: "p5", name: "Livia Saris", avatarColor: "pink", admission: "emergency", status: "critical", conditions: ["Migraine", "Post-op"], nextAppointment: "2026-12-24" },
  { id: "p6", name: "Jaydon Aminoff", avatarColor: "lime", admission: "outpatient", status: "stable", conditions: ["Diabetes"], nextAppointment: "2026-02-22" },
  { id: "p7", name: "Maria Lubin", avatarColor: "blue", admission: "inpatient", status: "critical", conditions: ["Pregnancy"], nextAppointment: "2026-04-10" },
  { id: "p8", name: "Ann Press", avatarColor: "neutral", admission: "discharged", status: "stable", conditions: ["Hypertension"], nextAppointment: "2026-08-10" },
  { id: "p9", name: "Terry Vaccaro", avatarColor: "blue", admission: "discharged", status: "recovering", conditions: ["Allergy", "Pregnancy"], nextAppointment: "2026-12-04" },
  { id: "p10", name: "Ruben Rosser", avatarColor: "blue", admission: "outpatient", status: "treatment", conditions: ["Migraine", "Post-op"], nextAppointment: "2026-10-01" },
  { id: "p11", name: "Ruben Curtis", avatarColor: "neutral", admission: "discharged", status: "recovering", conditions: ["Allergy", "Fracture"], nextAppointment: "2026-08-21" },
  { id: "p12", name: "Wilson Vetrovs", avatarColor: "blue", admission: "discharged", status: "stable", conditions: ["Pregnancy", "Diabetes"], nextAppointment: "2026-08-17" },
];

export const MEDICAL_NOTIFICATIONS: BellNotification[] = [
  { id: "n1", title: "High heart rate", description: "Above 120 BPM for 10 minutes while inactive.", time: "8m ago", icon: RiHeartPulseLine, tone: "error" },
  { id: "n2", title: "Lab results ready", description: "Cholesterol and glucose are in the normal range.", time: "1h ago", icon: RiTestTubeLine, tone: "success" },
  { id: "n3", title: "Medication reminder", description: "You missed your 9:00 AM dose of Metoprolol.", time: "3h ago", icon: RiMedicineBottleLine, tone: "information" },
  { id: "n4", title: "Appointment confirmed", description: "Dr. Clarkson, Thursday at 10:30.", time: "Yesterday", icon: RiCalendarCheckLine },
  { id: "n5", title: "Medical ID updated", description: "Emergency contact and allergies were changed.", time: "2d ago", icon: RiAsterisk },
];

const SECTIONS: DashboardSection[] = [
  { id: "profile", label: "Patient details" },
  { id: "steps", label: "Steps" },
  { id: "sleep", label: "Sleep score" },
  { id: "days", label: "Most active days" },
  { id: "activity", label: "Activity rings" },
  { id: "alerts", label: "Important alerts" },
  { id: "patients", label: "Patients table" },
];

const ACTION_COPY: Record<Exclude<PatientAction, "archive">, (name: string) => string> = {
  view: (name) => `Opened ${name}'s chart`,
  edit: (name) => `Editing ${name}'s record`,
  book: (name) => `Appointment request sent to ${name}`,
  message: (name) => `Message thread with ${name} opened`,
};

/* --------------------------------------------------------------- component */

export interface MedicalProfileProps {
  /** Rows of the patients table. */
  patients?: Patient[];
  /** Bell contents; the unread count drives the badge. */
  defaultNotifications?: BellNotification[];
  /** Sidebar key of the view shown first. "medical" is the dashboard. */
  defaultView?: string;
  /** Last day with data; later days in the activity calendar are empty. */
  today?: CalendarDate;
  className?: string;
}

const HOME_VIEW = "medical";

export function MedicalProfile({
  patients: initialPatients = MEDICAL_PATIENTS,
  defaultNotifications = MEDICAL_NOTIFICATIONS,
  defaultView = HOME_VIEW,
  today = parseDate("2026-07-10"),
  className,
}: MedicalProfileProps) {
  const [view, setView] = useState(defaultView);
  const [visible, setVisible] = useState<Set<string>>(() => new Set(SECTIONS.map((s) => s.id)));
  const [notifications, setNotifications] = useState<BellNotification[]>(defaultNotifications);
  const [patients, setPatients] = useState<Patient[]>(initialPatients);
  const [day, setDay] = useState<CalendarDate>(today);
  const activity = useMemo(() => sampleDayActivity(day), [day]);
  const navItem = DASHBOARD_NAV.find((item) => item.key === view);
  const show = (id: string) => visible.has(id);

  // #region critical
  // The sidebar's rows are `href="#"` links. One capture listener turns a
  // click on any of them into a view switch, so the host URL never changes.
  const onNavClickCapture = (event: MouseEvent<HTMLDivElement>) => {
    if (!(event.target instanceof Element)) return;
    const link = event.target.closest('a[href="#"]');
    if (!link) return;
    event.preventDefault();
    const item = DASHBOARD_NAV.find((entry) => entry.label === link.getAttribute("aria-label"));
    if (item) setView(item.key);
  };

  const fileReport = (report: FiledReport) => {
    const kind = REPORT_KINDS.find((k) => k.id === report.kind)?.label ?? "Report";
    setNotifications((list) => [
      { id: `report-${list.length + 1}`, title: `${kind} filed`, description: report.details, time: "Just now", icon: RiFileList3Line, tone: "success" },
      ...list,
    ]);
    toast.success("Report filed", { description: `${kind} sent to Dr. Clarkson.` });
  };

  const onPatientAction = (action: PatientAction, patient: Patient) => {
    if (action !== "archive") {
      toast(ACTION_COPY[action](patient.name));
      return;
    }
    const index = patients.findIndex((p) => p.id === patient.id);
    setPatients((list) => list.filter((p) => p.id !== patient.id));
    toast(`${patient.name} archived`, {
      actions: [
        {
          label: "Undo",
          onClick: () =>
            setPatients((list) => {
              if (list.some((p) => p.id === patient.id)) return list;
              const next = [...list];
              next.splice(Math.max(index, 0), 0, patient);
              return next;
            }),
        },
      ],
    });
  };
  // #endregion

  const isHome = view === HOME_VIEW;
  const title = isHome ? "Medical Profile" : (navItem?.label ?? "Medical Profile");

  return (
    <div
      className={cx("relative flex h-full w-full gap-3 overflow-hidden bg-background-full p-3", className)}
      onClickCapture={onNavClickCapture}
    >
      <DashboardSidebar selected={view} showThemeToggle={false} />

      <main className="flex min-h-0 min-w-0 flex-1 flex-col gap-4 overflow-y-auto overscroll-contain px-1 pt-1.5 pb-3">
        <DashboardPageHeader
          title={title}
          breadcrumbs={[
            { label: "Acme team", initials: "A", tone: "blue", onPress: () => setView("home") },
            { label: "Jordan", initials: "J", onPress: () => setView("profile") },
            { label: title, icon: navItem?.icon ?? RiAsterisk },
          ]}
          notifications={
            <NotificationBellBadge notifications={notifications} onNotificationsChange={(next) => setNotifications([...next])} />
          }
          actions={
            isHome ? (
              <>
                <SectionFilter sections={SECTIONS} visible={visible} onVisibleChange={setVisible} />
                <FileReportDialog onSubmit={fileReport} />
              </>
            ) : null
          }
        />

        {isHome ? (
          <>
            <div className="grid grid-cols-3 gap-4">
              {show("profile") ? <PatientProfileCard /> : null}
              {show("steps") ? <StepsCard chartHeight={196} /> : null}
              {show("sleep") ? <SleepScoreCard /> : null}
              {show("days") ? (
                <MostActiveDaysCard today={today} selected={day} onSelectedChange={setDay} height={232} />
              ) : null}
              {show("activity") ? (
                <ActivityRingsCard title={`Activity for ${formatLongDate(day)}`} rings={activity.rings} />
              ) : null}
              {show("alerts") ? (
                // Out of flow so its long list cannot stretch the row; it takes
                // the row height set by its neighbours and scrolls inside.
                <div className="relative min-h-[330px]">
                  <ImportantAlertsCard className="absolute inset-0 h-auto" />
                </div>
              ) : null}
            </div>
            {show("patients") ? (
              <PatientsTable patients={patients} pageSize={8} onAction={onPatientAction} aria-label="Patients" />
            ) : null}
            {visible.size === 0 ? (
              <p className="py-16 text-center text-body-regular text-text-secondary">
                Every card is hidden. Turn some back on from Filters.
              </p>
            ) : null}
          </>
        ) : (
          <WorkspacePlaceholder
            icon={navItem?.icon ?? RiAsterisk}
            label={navItem?.label ?? title}
            homeLabel="Medical Report"
            onBack={() => setView(HOME_VIEW)}
          />
        )}
      </main>
      <Toaster position="bottom-end" />
    </div>
  );
}

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Medical Profile" (boardui.com/templates/medical-profile).
 * No BoardUI source was used.
 */
"use client";

import { useEffect, useId, useRef, useState, type ComponentType } from "react";
import {
  RiAddLine,
  RiArrowLeftLine,
  RiAsterisk,
  RiDropLine,
  RiFileAddLine,
  RiFilter3Line,
  RiMenLine,
  RiStethoscopeLine,
} from "@remixicon/react";

import { Avatar } from "@/components/motion/avatar";
import { Button } from "@/components/motion/button";
import { Checkbox } from "@/components/motion/checkbox";
import { Modal, ModalBody, ModalFooter, ModalHeader, ModalTrigger } from "@/components/motion/modal";
import { Popover, PopoverFooter, PopoverHeader, PopoverTrigger } from "@/components/motion/popover";
import { Select, SelectItem } from "@/components/motion/select";
import { Textarea } from "@/components/motion/textarea";
import { cx } from "@/lib/cx";

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

/* ------------------------------------------------------------ patient card */

export interface ProfileDetail {
  icon: IconComponent;
  label: string;
  value: string;
}

export const PROFILE_DETAILS: ProfileDetail[] = [
  { icon: RiAsterisk, label: "Date of Birth", value: "28 July, 1997" },
  { icon: RiMenLine, label: "Gender", value: "Male" },
  { icon: RiDropLine, label: "Blood Type", value: "A rh+" },
  { icon: RiStethoscopeLine, label: "GP Doctor", value: "Mattheus Clarkson" },
];

export interface PatientProfileCardProps {
  name?: string;
  initials?: string;
  details?: ProfileDetail[];
  className?: string;
}

/**
 * Avatar, name and four detail rows. The "+" opens the file picker; the chosen
 * image is shown through an object URL that is revoked when it is replaced or
 * the card unmounts.
 */
export function PatientProfileCard({
  name = "Jordan Lee",
  initials = "J",
  details = PROFILE_DETAILS,
  className,
}: PatientProfileCardProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [photo, setPhoto] = useState<string | null>(null);

  useEffect(() => {
    if (!photo) return;
    return () => URL.revokeObjectURL(photo);
  }, [photo]);

  return (
    <section
      aria-label={`${name}, patient details`}
      className={cx(
        "flex w-full min-w-0 flex-col items-center gap-4 rounded-2xl bg-background-secondary-default px-2.5 pt-6 pb-2.5",
        className,
      )}
    >
      <div className="relative">
        <Avatar
          size="lg"
          initials={initials}
          src={photo ?? undefined}
          alt={photo ? `${name}'s photo` : undefined}
          className="size-[66px] text-[26px] leading-none"
        />
        <Button
          variant="secondary"
          size="xs"
          iconOnly
          leadingIcon={RiAddLine}
          aria-label={photo ? "Change profile photo" : "Add profile photo"}
          onClick={() => inputRef.current?.click()}
          className="absolute -end-1 -top-1 rounded-full"
        />
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          tabIndex={-1}
          aria-hidden
          className="sr-only"
          onChange={(event) => {
            const file = event.currentTarget.files?.[0];
            if (file) setPhoto(URL.createObjectURL(file));
            event.currentTarget.value = "";
          }}
        />
      </div>
      <p className="text-title-2-medium whitespace-nowrap text-text-primary">{name}</p>
      <dl className="flex w-full flex-1 flex-col justify-end gap-2.5">
        {details.map((detail) => (
          <div
            key={detail.label}
            className="flex w-full items-center justify-between gap-3 rounded-2lg bg-background-inner-default px-2.5 py-2"
          >
            <dt className="flex min-w-0 items-center gap-1.5 text-body-regular text-text-secondary">
              <detail.icon className="size-4 shrink-0" aria-hidden />
              <span className="truncate">{detail.label}</span>
            </dt>
            <dd className="text-body-medium whitespace-nowrap text-text-primary">{detail.value}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

/* ---------------------------------------------------------- section filter */

export interface DashboardSection {
  id: string;
  label: string;
}

export interface SectionFilterProps {
  sections: DashboardSection[];
  /** Ids currently shown. */
  visible: ReadonlySet<string>;
  onVisibleChange: (next: Set<string>) => void;
}

/** "Filters": a popover of checkboxes that show or hide the dashboard's cards. */
export function SectionFilter({ sections, visible, onVisibleChange }: SectionFilterProps) {
  const hidden = sections.length - sections.filter((s) => visible.has(s.id)).length;
  const toggle = (id: string, on: boolean) => {
    const next = new Set(visible);
    if (on) next.add(id);
    else next.delete(id);
    onVisibleChange(next);
  };

  return (
    <PopoverTrigger>
      <Button variant="secondary" leadingIcon={RiFilter3Line} aria-label={hidden ? `Filters, ${hidden} hidden` : "Filters"}>
        Filters
        {hidden > 0 ? (
          <span className="ms-1 rounded-md bg-background-tertiary-default px-1.5 text-caption-1-medium text-text-secondary tabular-nums">
            {hidden}
          </span>
        ) : null}
      </Button>
      <Popover placement="bottom end" className="w-[264px]" dialogClassName="flex flex-col gap-3 p-3">
        <PopoverHeader title="Show on dashboard" description="Hidden cards come back from here." />
        <div className="flex flex-col gap-2">
          {sections.map((section) => (
            <Checkbox
              key={section.id}
              isSelected={visible.has(section.id)}
              onChange={(on) => toggle(section.id, on)}
            >
              {section.label}
            </Checkbox>
          ))}
        </div>
        <PopoverFooter>
          <Button
            variant="ghost"
            size="small"
            disabled={hidden === 0}
            onClick={() => onVisibleChange(new Set(sections.map((s) => s.id)))}
          >
            Show all
          </Button>
        </PopoverFooter>
      </Popover>
    </PopoverTrigger>
  );
}

/* ------------------------------------------------------------ file report */

export type ReportKind = "symptom" | "medication" | "lab" | "appointment";

export const REPORT_KINDS: { id: ReportKind; label: string }[] = [
  { id: "symptom", label: "New symptom" },
  { id: "medication", label: "Medication issue" },
  { id: "lab", label: "Lab result question" },
  { id: "appointment", label: "Appointment change" },
];

export interface FiledReport {
  kind: ReportKind;
  details: string;
}

/** Primary "File a report" button and its form dialog. */
export function FileReportDialog({ onSubmit }: { onSubmit: (report: FiledReport) => void }) {
  const formId = useId();
  const [isOpen, setOpen] = useState(false);
  const [kind, setKind] = useState<ReportKind>("symptom");
  const [details, setDetails] = useState("");
  const ready = details.trim().length > 0;

  const close = () => {
    setOpen(false);
    setDetails("");
    setKind("symptom");
  };

  return (
    <ModalTrigger isOpen={isOpen} onOpenChange={(open) => (open ? setOpen(true) : close())}>
      <Button leadingIcon={RiAddLine}>File a report</Button>
      <Modal size="sm">
        <ModalHeader
          icon={RiFileAddLine}
          title="File a report"
          description="Your GP, Mattheus Clarkson, sees it in their inbox right away."
        />
        <ModalBody>
          <form
            id={formId}
            className="flex flex-col gap-4"
            onSubmit={(event) => {
              event.preventDefault();
              if (!ready) return;
              onSubmit({ kind, details: details.trim() });
              close();
            }}
          >
            <Select
              label="Report type"
              selectedKey={kind}
              onSelectionChange={(key) => {
                if (key !== null) setKind(key as ReportKind);
              }}
              className="w-full"
              triggerClassName="w-full"
            >
              {REPORT_KINDS.map((option) => (
                <SelectItem key={option.id} id={option.id} textValue={option.label}>
                  {option.label}
                </SelectItem>
              ))}
            </Select>
            <Textarea
              label="Details"
              placeholder="What happened, and when?"
              rows={4}
              maxLength={280}
              showCount
              value={details}
              onChange={setDetails}
            />
          </form>
        </ModalBody>
        <ModalFooter>
          <Button variant="secondary" onClick={close}>
            Cancel
          </Button>
          <Button type="submit" form={formId} disabled={!ready}>
            Submit report
          </Button>
        </ModalFooter>
      </Modal>
    </ModalTrigger>
  );
}

/* ------------------------------------------------------------- other views */

export interface WorkspacePlaceholderProps {
  icon: IconComponent;
  label: string;
  /** Name of the page the button goes back to. */
  homeLabel: string;
  onBack: () => void;
}

/** What the other sidebar rows open: a quiet panel that points back to this template's page. */
export function WorkspacePlaceholder({ icon: Icon, label, homeLabel, onBack }: WorkspacePlaceholderProps) {
  return (
    <section
      aria-label={label}
      className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 rounded-2xl border border-dashed border-border-button-default bg-background-secondary-default p-10 text-center"
    >
      <span className="flex size-12 items-center justify-center rounded-full bg-background-primary-default text-foreground-icon-secondary shadow-xs">
        <Icon className="size-6" aria-hidden />
      </span>
      <div className="flex max-w-sm flex-col gap-1">
        <h2 className="text-title-3-medium text-text-primary">{label}</h2>
        <p className="text-body-regular text-text-secondary">
          {label} is a template of its own. This page is the {homeLabel} screen, so there is nothing to show here yet.
        </p>
      </div>
      <Button variant="secondary" leadingIcon={RiArrowLeftLine} onClick={onBack}>
        Back to {homeLabel}
      </Button>
    </section>
  );
}
